import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import '../../../../core/theme/app_theme.dart';

class LearnScreen extends StatefulWidget { const LearnScreen({super.key}); @override State<LearnScreen> createState()=>_LearnScreenState(); }
class _LearnScreenState extends State<LearnScreen>{final search=TextEditingController();@override void dispose(){search.dispose();super.dispose();}@override Widget build(BuildContext context){return Scaffold(backgroundColor:PennyPalColors.black,appBar:AppBar(backgroundColor:PennyPalColors.black,title:const Text('Learn',style:TextStyle(color:Colors.white,fontWeight:FontWeight.w800))),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('learningContent').orderBy('createdAt',descending:true).snapshots(),builder:(context,s){if(s.hasError)return Center(child:Text('Could not load learning content: ${s.error}',style:const TextStyle(color:Colors.white)));if(!s.hasData)return const Center(child:CircularProgressIndicator());final q=search.text.toLowerCase();final docs=s.data!.docs.where((d)=>'${d.data()['title']??''} ${d.data()['summary']??''} ${d.data()['category']??''}'.toLowerCase().contains(q)).toList();return Column(children:[Padding(padding:const EdgeInsets.all(20),child:TextField(controller:search,onChanged:(_)=>setState((){}),style:const TextStyle(color:Colors.white),decoration:const InputDecoration(hintText:'Search lessons',prefixIcon:Icon(Icons.search),filled:true,fillColor:PennyPalColors.surface))),Expanded(child:docs.isEmpty?const Center(child:Text('No learning content is available yet.',style:TextStyle(color:PennyPalColors.gray))):ListView.separated(padding:const EdgeInsets.all(20),itemCount:docs.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(_,i){final d=docs[i];final v=d.data();return ListTile(onTap:()=>context.push('/learn/${d.id}'),tileColor:PennyPalColors.surface,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(14)),leading:const Icon(Icons.menu_book,color:Colors.white),title:Text('${v['title']??'Untitled lesson'}',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w700)),subtitle:Text('${v['summary']??v['category']??''}',style:const TextStyle(color:PennyPalColors.gray)),trailing:const Icon(Icons.chevron_right,color:Colors.white));}))]);}));}}
